{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who else is involved in the morning routine — whether a partner, family member, or caregiver also participates or whether the parent is the sole actor.",
      "why_it_matters": "Knowing all actors determines which steps can be delegated or automated and where handoffs occur."
    },
    {
      "category": "decision",
      "gap": "The threshold or criteria for deciding 'we are running late' is not defined — no time target or trigger is specified.",
      "why_it_matters": "Without a clear decision rule, it is impossible to automate or even consistently detect the late-running condition."
    },
    {
      "category": "system",
      "gap": "No system or channel is identified for notifying someone when running late — it could be a phone call, messaging app, childcare portal, or other means.",
      "why_it_matters": "The notification step's automation potential depends entirely on which communication channel or system is used."
    },
    {
      "category": "output",
      "gap": "It is unclear what constitutes a successful drop-off — whether a sign-in, handover confirmation, or attendance record is produced.",
      "why_it_matters": "A defined output is needed to confirm process completion and to assess whether any record-keeping step can be automated."
    },
    {
      "category": "manual_effort",
      "gap": "The specific tasks involved in 'getting the child ready' and 'packing what we need' are not enumerated, so the volume and nature of manual effort is unknown.",
      "why_it_matters": "Identifying discrete manual steps is essential for spotting automation or checklist-tool opportunities."
    },
    {
      "category": "exception",
      "gap": "No exceptions beyond running late are described — for example, childcare closure, child illness, or forgotten items are not mentioned.",
      "why_it_matters": "Unhandled exceptions create process failures; knowing them allows contingency paths to be designed or automated."
    },
    {
      "category": "frequency",
      "gap": "The schedule on which this workflow runs is not stated — which days of the week, how many times per week, and whether it varies.",
      "why_it_matters": "Frequency affects the priority and return-on-investment of any automation effort."
    },
    {
      "category": "dependency",
      "gap": "It is not clear whether the drop-off timing depends on external constraints such as childcare opening hours, a work start time, or a transport schedule.",
      "why_it_matters": "External dependencies set hard deadlines that must be reflected in any automated scheduling or alerting logic."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "What specific time or signal tells you that you are 'running late' — for example, is there a target departure time or a childcare opening deadline you are measuring against?",
      "targets": ["decision"]
    },
    {
      "id": "Q2",
      "question": "When you need to notify someone that you are running late, who do you contact and through what channel or system — for example, a phone call, a messaging app, or a childcare centre portal?",
      "targets": ["system", "actor"]
    },
    {
      "id": "Q3",
      "question": "Can you list the individual tasks involved in getting your child ready and packing — for example, preparing food, locating items, dressing — so we understand the full set of manual steps?",
      "targets": ["manual_effort"]
    },
    {
      "id": "Q4",
      "question": "Is there a sign-in, handover confirmation, or attendance record produced at drop-off, and if so, how is it captured?",
      "targets": ["output"]
    },
    {
      "id": "Q5",
      "question": "On which days of the week does this routine occur, and does the schedule vary — for example, different days in different weeks?",
      "targets": ["frequency"]
    },
    {
      "id": "Q6",
      "question": "What do you do if an unexpected situation arises that prevents the normal drop-off — such as the childcare centre being closed or your child being unwell?",
      "targets": ["exception"]
    }
  ]
}
